const input = $input.first().json;
const body = $('Webhook').first().json.body;
const calculated = parseFloat(input.fuel_litres_calculated || 0);
const reported = parseFloat(input.fuel_litres_reported || 0);

let delta = 0;
if (calculated > 0) {
  delta = Math.abs(calculated - reported) / calculated * 100;
} else if (reported > 0) {
  delta = 100;
}

const has_anomaly = delta > 15;
let anomaly_note = null;
let alert_message = null;

if (has_anomaly) {
  const diff = Math.abs(calculated - reported).toFixed(1);
  const percent = delta.toFixed(1);

  if (calculated > reported) {
    anomaly_note = `Можливий злив палива. Спожито за розрахунками на ${diff} л (${percent}%) більше, ніж заправлено.`;
  } else {
    anomaly_note = `Некоректний ввід заправок або перевантаження генератора. Заправлено на ${diff} л (${percent}%) більше, ніж витрачено за розрахунками.`;
  }

  alert_message = `⚠️ Аномальний розхід на локації <b>${input.location_name}</b> за період ${body.period_start} — ${body.period_end}:\n\n${anomaly_note}\n\nРозраховано: ${calculated.toFixed(1)} л\nЗаправлено: ${reported.toFixed(1)} л`;
}

return {
  ...input,
  ...body,
  delta_calculated_reported: parseFloat(delta.toFixed(2)),
  has_anomaly,
  anomaly_note,
  alert_message
};
